<template>
  <view class="tabbar" :style="{ height: tabBarHeight + 'px', paddingBottom: safeBottom + 'px' }">
    <view 
      class="tab-item" 
      
      :class="{ active: current === 0 }"
    >
      <image 
        :src="current === 0 ? activeHome : normalHome" 
        class="tab-img"
        mode="widthFix"
        @click="goToPage(0)"
      ></image>
      <!-- <text class="tab-text" :class="{ active: current === 0 }">首页</text> -->
    </view>
    <view v-if="isShowMiddle"
      class="tab-item" 
      :class="{ active: current === 1 }"
    >
      <image 
        :src="current === 1 ? activeYou : normalYou" 
        class="tab-img"
        mode="widthFix"
        @click="goToPage(1)"
      ></image>
      <!-- <text class="tab-text" :class="{ active: current === 0 }">首页</text> -->
    </view>
    <view  v-if="isShowMiddle"
      class="tab-item" 
    
      :class="{ active: current === 2 }"
    >
      <image 
        :src="current === 2 ? activeMine : normalMine" 
        class="tab-img"
        mode="widthFix"
        @click="goToPage(2)"
      ></image>
      <!-- <text class="tab-text" :class="{ active: current === 1 }">我的</text> -->
    </view>
    <view  v-else
      class="tab-item" 
    
      :class="{ active: current === 1 }"
    >
      <image 
        :src="current === 1 ? activeMine : normalMine" 
        class="tab-img"
        mode="widthFix"
        @click="goToPage(1)"
      ></image>
      <!-- <text class="tab-text" :class="{ active: current === 1 }">我的</text> -->
    </view>
  </view>
</template>

<script>
import {
  getTopTabList,
} from "@/api/demo";
export default {
  name: 'CustomTabBar',
  props: {
    // 当前选中索引（0：首页，1：我的）
    current: {
      type: Number,
      default: 0,
      validator: (val) => [0, 1].includes(val) // 校验值范围
    },
    // 选中颜色（外部可自定义）
    activeColor: {
      type: String,
      default: '#007aff'
    }
  },
  watch:{
  },
  data() {
    return {
      // 图标路径（统一绝对路径，避免引用错误）
      normalHome: '../../static/home1.png',
      activeHome: '../../static/home.png',
      normalMine: '../../static/mine.png',
      activeMine: '../../static/mine1.png',
      normalYou:'../../static/cai.png',
      activeYou:'../../static/cai1.png',
      // 基础高度（不含安全区）
      baseTabHeight: 50,
      // 安全区底部距离（适配全面屏）
      safeBottom: 0,
      // 页面路径（与tab索引对应）
      pagePaths: ['/pages/index/index','/pages/ticket/ticket', '/pages/user/index'],
      isShowMiddle: false,
    };
  },
  computed: {
    // 计算最终TabBar高度（基础高度+安全区）
    tabBarHeight() {
      return this.baseTabHeight + this.safeBottom;
    },
  },
  mounted() {
    // 适配不同设备安全区
    this.calcSafeArea();
    // 监听窗口变化（如旋转屏幕）
    uni.onWindowResize(() => this.calcSafeArea());
  },
  onUnload() {
    // 解绑事件，避免内存泄漏
    uni.offWindowResize(() => this.calcSafeArea());
  },
  created() {
    this.getTabBar();
  },
  methods: {
    /**
     * 计算安全区底部距离
     */
    calcSafeArea() {
      try {
        const systemInfo = uni.getSystemInfoSync();
        // 微信小程序/App/H5 安全区字段兼容
        this.safeBottom = systemInfo.safeAreaInsets?.bottom || 0;
        // 特殊设备兜底（避免安全区过大）
        if (this.safeBottom > 30) this.safeBottom = 30;
      } catch (e) {
        this.safeBottom = 0;
        console.warn('安全区计算失败，使用默认值：', e);
      }
    },

    /**
     * 跳转页面
     * @param {Number} index - 页面索引
     */
    goToPage(index) {
      console.log(index, 'index----------')
      // 避免重复跳转
      if (index === this.current) return;
      // 校验路径合法性
      const targetUrl = this.pagePaths[index];
      console.log(targetUrl, 'url--------------')
      if (!targetUrl) {
        console.error('无效页面路径，索引：', index);
        return;
      }
      // 跳转（tab页必须用switchTab）
      uni.switchTab({
        url: targetUrl,
        fail: (err) => {
          console.error('Tab页面跳转失败：', err);
          // 失败时降级用navigateTo（兼容特殊场景）
          uni.navigateTo({ url: targetUrl });
        }
      });
    },
  async getTabBar() {
    try {
      const res = await getTopTabList();
      // 严格校验接口返回格式，避免undefined错误
      const isShowDG = res?.data?.isShowDG ?? 0; // 默认为0
      this.isShowMiddle = isShowDG === 1;
      // 根据isShowMiddle重置pagePaths，避免索引错误
      this.pagePaths = this.isShowMiddle 
        ? ['/pages/index/index', '/pages/ticket/ticket', '/pages/user/index']
        : ['/pages/index/index', '/pages/user/index'];
    } catch (err) {
      console.error('TabBar接口调用失败：', err);
      // 失败时使用默认配置，确保TabBar至少显示基础内容
      this.isShowMiddle = false; // 或true，根据需求设置
      this.pagePaths = ['/pages/index/index', '/pages/user/index'];
    }
  }
  }
};
</script>

<style lang="scss" scoped>
/* TabBar容器 */
.tabbar {
  display: flex;
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  background-color: #fff;
  border-top: 1px solid #eee;
  z-index: 999999999;
  box-sizing: border-box;
  height: 100rpx;
}

/* Tab项（平均分配宽度） */
.tab-item {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 5px 0;
  transition: background-color 0.2s ease;

  /* 选中时背景高亮（可选） */
  &.active {
    background-color: #f8f8f8;
  }
}

/* Tab图标 */
.tab-img {
  width: 24px;
  height: 24px;
  opacity: 1 !important;
  visibility: visible !important;
}

/* Tab文字 */
.tab-text {
  font-size: 12px;
  color: #8e8e93;
  margin-top: 2px;
  transition: color 0.2s ease;

  &.active {
    color: v-bind(activeColor);
    font-weight: 500;
  }
}
</style>